DELETE FROM tehtava WHERE nimi = 'Maakivien (< 1 m3) poisto päällystetyltä tieltä'; -- Väärin Harjaan luotu tehtävä, tarpeeton. Ei kirjauksia, poistetaan.
UPDATE tehtavaryhma SET nimi = 'T4' WHERE nimi = 'T4 - Digitalisaatio ja innovaatiot' -- Muutetaan nimi, koska tehtäväryhmän käyttö laajempaa kuin vain digitalitalisaatioon ja innovaatioihin liittyvää.
